static lstr L1102 = {0, 6096, "// std/bytes: byte strings, and their text forms in hex (base 16) and base64 (RFC 4648). The\012// conversion functions and slicing are built into the compiler.\012\012import * as Bytes from \"std/bytes\"\012import * as Str from \"std/string\"\012import * as Arrays from \"std/array\"\012import * as Int from \"std/int\"\012import * as U8 from \"std/u8\"\012\012const HEX_DIGITS = \"0123456789abcdef\"\012const BASE64_ALPHABET = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"\012const BASE64_URL_ALPHABET = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_\"\012\012/// Writes each byte as two lowercase hex digits, with no separator and no prefix.\012export function toHex(data: bytes): string uses alloc {\012  let builder = Str.builder()\012  for (const byte of Arrays.values(Bytes.toArray(data))) {\012    const value = Int.from(byte)\012    Str.appendChar(mutable builder, Str.charAt(HEX_DIGITS, value >> 4))\012    Str.appendChar(mutable builder, Str.charAt(HEX_DIGITS, value & 15))\012  }\012  return Str.build(builder)\012}\012\012/// Reads pairs of hex digits, upper or lower case, as bytes. Gives `None` for an odd length or a\012/// character that is not a hex digit. The empty text gives empty bytes.\012export function fromHex(text: string): Option<bytes> uses alloc {\012  const length = Str.length(text)\012  if (length % 2 != 0) {\012    return None\012  }\012  let items: Array<u8> = []\012  let index = 0\012  while (index < length) {\012    const high = readHexDigit(Str.byteAt(text, index))\012    const low = readHexDigit(Str.byteAt(text, index + 1))\012    if (high < 0 || low < 0) {\012      return None\012    }\012    Arrays.push(mutable items, U8.wrap(high * 16 + low))\012    index += 2\012  }\012  return Some(Bytes.fromArray(items))\012}\012\012/// Writes the bytes as base64 with the standard alphabet (`A-Z`, `a-z`, `0-9`, `+`, `/`) and `=`\012/// padding to a multiple of four characters.\012export function toBase64(data: bytes): string uses alloc {\012  return writeBase64(data, BASE64_ALPHABET, true)\012}\012\012/// Writes the bytes as base64 with the URL-safe alphabet (`-` and `_` in place of `+` and `/`).\012/// `padded` adds `=` padding to a multiple of four characters; false leaves it off.\012export function toBase64Url(data: bytes, padded: bool): string uses alloc {\012  return writeBase64(data, BASE64_URL_ALPHABET, padded)\012}\012\012/// Reads base64 text with the standard alphabet. The padding must be exact: the length is a\012/// multiple of four and `=` fills the last group. Gives `None` for any other character, for\012/// misplaced or missing padding, and for leftover bits that are not zero.\012export function fromBase64(text: string): Option<bytes> uses alloc {\012  return readBase64(text, false)\012}\012\012/// Reads base64 text with the URL-safe alphabet, with or without `=` padding. Gives `None` for any\012/// other character, for padding that does not fit the length, and for leftover bits that are not\012/// zero.\012export function fromBase64Url(text: string): Option<bytes> uses alloc {\012  return readBase64(text, true)\012}\012\012function readHexDigit(byte: int): int {\012  if (byte >= 48 && byte <= 57) {\012    return byte - 48\012  }\012  if (byte >= 97 && byte <= 102) {\012    return byte - 87\012  }\012  if (byte >= 65 && byte <= 70) {\012    return byte - 55\012  }\012  return -1\012}\012\012function readBase64Digit(byte: int, urlSafe: bool): int {\012  if (byte >= 65 && byte <= 90) {\012    return byte - 65\012  }\012  if (byte >= 97 && byte <= 122) {\012    return byte - 71\012  }\012  if (byte >= 48 && byte <= 57) {\012    return byte + 4\012  }\012  // The last two digits differ between the alphabets.\012  if (urlSafe) {\012    if (byte == 45) {\012      return 62\012    }\012    if (byte == 95) {\012      return 63\012    }\012    return -1\012  }\012  if (byte == 43) {\012    return 62\012  }\012  if (byte == 47) {\012    return 63\012  }\012  return -1\012}\012\012function writeBase64(data: bytes, alphabet: string, padded: bool): string uses alloc {\012  let builder = Str.builder()\012  let buffer = 0\012  let bitCount = 0\012  let characterCount = 0\012  for (const byte of Arrays.values(Bytes.toArray(data))) {\012    // Take eight bits, then emit every full group of six.\012    buffer = (buffer << 8) | Int.from(byte)\012    bitCount += 8\012    while (bitCount >= 6) {\012      bitCount -= 6\012      const shift = bitCount\012      if (shift >= 0 && shift < 64) {\012        Str.appendChar(mutable builder, Str.charAt(alphabet, (buffer >> shift) & 63))\012        characterCount++\012      }\012    }\012    const keepBits = bitCount\012    if (keepBits >= 0 && keepBits < 64) {\012      buffer = buffer & ((1 << keepBits) - 1)\012    }\012  }\012  // The last partial group is padded with zero bits.\012  const missingBits = 6 - bitCount\012  if (bitCount > 0 && missingBits >= 0 && missingBits < 64) {\012    Str.appendChar(mutable builder, Str.charAt(alphabet, (buffer << missingBits) & 63))\012    characterCount++\012  }\012  if (padded) {\012    while (characterCount % 4 != 0) {\012      Str.append(mutable builder, \"=\")\012      characterCount++\012    }\012  }\012  return Str.build(builder)\012}\012\012function readBase64(text: string, urlSafe: bool): Option<bytes> uses alloc {\012  const length = Str.length(text)\012  // Trailing `=` is padding; at most two of them.\012  let end = length\012  while (end > 0 && Str.byteAt(text, end - 1) == 61) {\012    end--\012  }\012  const paddingCount = length - end\012  if (paddingCount > 2) {\012    return None\012  }\012  const remainder = end % 4\012  if (remainder == 1) {\012    return None\012  }\012  if (paddingCount > 0) {\012    if (length % 4 != 0) {\012      return None\012    }\012  } else if (remainder != 0 && !urlSafe) {\012    return None\012  }\012  let items: Array<u8> = []\012  let buffer = 0\012  let bitCount = 0\012  let index = 0\012  while (index < end) {\012    // Six bits per character; emit a byte whenever eight are ready.\012    const digit = readBase64Digit(Str.byteAt(text, index), urlSafe)\012    if (digit < 0) {\012      return None\012    }\012    buffer = (buffer << 6) | digit\012    bitCount += 6\012    if (bitCount >= 8) {\012      bitCount -= 8\012      const shift = bitCount\012      if (shift >= 0 && shift < 64) {\012        Arrays.push(mutable items, U8.wrap((buffer >> shift) & 255))\012        buffer = buffer & ((1 << shift) - 1)\012      }\012    }\012    index++\012  }\012  // Leftover bits must be zero, or the text is not what an encoder writes.\012  if (buffer != 0) {\012    return None\012  }\012  return Some(Bytes.fromArray(items))\012}\012"};
