static lstr L1470 = {0, 446, "// std/internal/clock. The monotonic clock and the wall clock.\012#include <time.h>\012\012static int64_t narra_clock_monotonic_nanos(void) {\012  struct timespec now;\012  clock_gettime(CLOCK_MONOTONIC, &now);\012  return (int64_t)now.tv_sec * 1000000000 + (int64_t)now.tv_nsec;\012}\012\012static int64_t narra_clock_wall_millis(void) {\012  struct timespec now;\012  clock_gettime(CLOCK_REALTIME, &now);\012  return (int64_t)now.tv_sec * 1000 + (int64_t)now.tv_nsec / 1000000;\012}\012"};
